-- fullbatch116_danielle_load.sql — Book Dash 전량 116권 Danielle 오디오 book_audio 적재
-- 생성: scripts/tts_pilot/gen_book_audio_sql.py (워커, DB 접속 0건)
-- 근거: ADR-0053(전량 확장) / ADR-0034(결정 ①②③ + Amd#1 kind · Amd#2 성우 층위) / ADR-0052 Amd#2
--
-- ★ 실행은 팀장 영역(Supabase SQL Editor). ★ 선행 조건: Storage 업로드 완료
--   (docs/ops/tts-fullbatch-upload.md 1~3단계). audio_path가 가리키는 오브젝트가 없으면
--   행만 생기고 재생이 깨진다 — 업로드 검증을 반드시 먼저 통과할 것.
--
-- 규모: 116권 / 1464행 (page 1348 + cover 116)
-- 값  : voice='danielle' · engine='long-form' · rate=85 (atempo 0.85의 실효 속도, SSML prosody 아님)
--        duration_ms = 감속 후 mp3 실측(ffmpeg). 마크 프록시 아님.
--        audio_path/marks_path = 버킷명 미포함 **오브젝트 키만** (ADR-0034)
--
-- page_index 축: 파일명 pNN은 1-based, 컬럼 page_index는 0-based → page_index = NN - 1.
--   표지는 page_index=0 고정 placeholder이며 kind='cover'로 본문 첫 면과 구분된다
--   (UNIQUE에 kind 포함 — ADR-0034 Amd#1).
--
-- UNIQUE (book_id, kind, page_index, voice) 충돌 검토:
--   · 파일럿 12권과 본 116권은 **교집합 0**(로컬 산출물 대조 확인) → 신규 삽입만 발생
--   · 구 44권은 voice='Ruth'라 voice가 달라 자연 분리 — 건드리지 않는다
--   · 권 내 (kind, page_index) 중복은 생성 단계에서 검사 통과(중복 0건)
--   · ON CONFLICT DO UPDATE 채택 — 재실행 안전(경로·길이 정정 반영).
--     절대 덮어쓰지 않으려면 DO UPDATE SET 블록을 DO NOTHING 으로 바꿔 실행할 것.
--
-- SQL Editor 표시 100행 제한 대응: 모든 검증문을 COUNT 기반으로 작성했다(행 나열 없음).

BEGIN;

-- ============================================================
-- [0] 사전검증 — 현재 danielle 행이 '파일럿 12권'뿐인지
-- ============================================================
-- 기대: books 12 / rows 150 / page 138 / cover 12  (파일럿 적재분만 존재)
-- 이 수치가 다르면 이미 일부가 적재된 상태다. 그대로 진행해도 ON CONFLICT로 안전하나,
-- 원인을 먼저 확인할 것(중복 실행? 다른 배치?).
SELECT count(DISTINCT book_id) AS danielle_books,
       count(*)                                   AS danielle_rows,
       count(*) FILTER (WHERE kind = 'page')      AS page_rows,
       count(*) FILTER (WHERE kind = 'cover')     AS cover_rows
  FROM public.book_audio WHERE voice = 'danielle';

-- 참고: 구 44권(voice='Ruth') 현황 — 본 적재가 건드리지 않음을 사후 대조할 기준값
-- 기대: books 44 / rows 574
SELECT count(DISTINCT book_id) AS ruth_books, count(*) AS ruth_rows
  FROM public.book_audio WHERE voice = 'Ruth';

