ON CONFLICT (book_id, kind, page_index, voice) DO UPDATE SET
  audio_path  = EXCLUDED.audio_path,
  marks_path  = EXCLUDED.marks_path,
  engine      = EXCLUDED.engine,
  rate        = EXCLUDED.rate,
  duration_ms = EXCLUDED.duration_ms;

-- ============================================================
-- [1-검증] 적재 결과 (COUNT 기반)
-- ============================================================
-- 기대: books 128 / rows 1614 / page 1486 / cover 128
--       (= 본 배치 + 기존 파일럿 12권 150행. 파일럿과 교집합이 없으므로 단순 합)
SELECT count(DISTINCT book_id) AS danielle_books,
       count(*)                                   AS danielle_rows,
       count(*) FILTER (WHERE kind = 'page')      AS page_rows,
       count(*) FILTER (WHERE kind = 'cover')     AS cover_rows
  FROM public.book_audio WHERE voice = 'danielle';

-- 표지 누락 권 (기대: 0) — 본문은 있는데 cover가 없는 danielle 책
SELECT count(*) AS books_missing_cover FROM (
  SELECT book_id FROM public.book_audio WHERE voice = 'danielle'
   GROUP BY book_id HAVING count(*) FILTER (WHERE kind = 'cover') = 0
) t;

-- 경로 규약 위반 (기대: 0) — 버킷명 접두사 혼입·성우 층위 누락 검출
SELECT count(*) AS bad_path FROM public.book_audio
 WHERE voice = 'danielle'
   AND (audio_path LIKE 'book-audio/%' OR audio_path NOT LIKE '%/danielle/%');

-- 구 44권 무간섭 확인 (기대: 위 [0]과 동일한 44 / 574)
SELECT count(DISTINCT book_id) AS ruth_books, count(*) AS ruth_rows
  FROM public.book_audio WHERE voice = 'Ruth';

-- ============================================================
-- [2] (선택) books.has_audio = true
-- ============================================================
-- ⚠ 2026-07-28 기준 **앱에서 has_audio 컬럼을 읽는 코드는 0건**이다.
--   상세 배지·카드 배지·리더 게이트·관리자 배지 전부 book_audio 행 존재로 판정한다
--   (selectReaderAudioBookIds — lib/book/audio-manifest.ts). 즉 이 UPDATE는
--   사용자 화면에 아무 영향이 없다. SQL 레벨 정합을 위해서만 남긴다 — 생략해도 무방.
-- 대상은 danielle 행을 가진 책 전체(파일럿 12 포함, 이미 true라 멱등).
UPDATE public.books SET has_audio = true
 WHERE has_audio = false
   AND id IN (SELECT DISTINCT book_id FROM public.book_audio WHERE voice = 'danielle');

-- 검증 기대: 128 (danielle 책 전체가 true)
SELECT count(*) AS has_audio_true FROM public.books
 WHERE has_audio = true
   AND id IN (SELECT DISTINCT book_id FROM public.book_audio WHERE voice = 'danielle');

-- ============================================================
-- [3] (선택) book_review.status: confirmed → tts_done
-- ============================================================
-- ADR-0046 D6 status 4단계. 공개 여부의 단일진실은 books.is_active이며 여기서 건드리지 않는다.
-- ⚠ 기대 건수를 로컬 산출물로는 알 수 없다(현재 status 분포는 DB만 안다).
--   아래 분포를 **먼저 조회**해 confirmed가 몇 권인지 확인한 뒤 UPDATE 여부를 판단할 것.
SELECT r.status, count(*) AS books
  FROM public.book_review r
 WHERE r.book_id IN (SELECT DISTINCT book_id FROM public.book_audio WHERE voice = 'danielle')
 GROUP BY r.status ORDER BY r.status;

UPDATE public.book_review SET status = 'tts_done'
 WHERE status = 'confirmed'
   AND book_id IN (SELECT DISTINCT book_id FROM public.book_audio WHERE voice = 'danielle');

-- 검증: 위 분포를 다시 조회해 confirmed → tts_done 이동을 확인
SELECT r.status, count(*) AS books
  FROM public.book_review r
 WHERE r.book_id IN (SELECT DISTINCT book_id FROM public.book_audio WHERE voice = 'danielle')
 GROUP BY r.status ORDER BY r.status;

COMMIT;

-- 롤백이 필요하면 COMMIT 전에 ROLLBACK; 을 실행한다.
-- 적재 후 되돌리려면: DELETE FROM public.book_audio WHERE voice='danielle' AND book_id IN (…116권…);
--   (파일럿 12권을 지우지 않도록 book_id 목록을 [0]의 IN 목록으로 한정할 것)
